private void pBPhoto_Click(object sender, EventArgs e)
{
    if (oFDPicture.ShowDialog() == DialogResult.OK)
    {
        fileNameToCopy = oFDPicture.FileName;
        fileName = oFDPicture.SafeFileName;
        pBPhoto.ImageLocation = fileNameToCopy;
        photochanged = true;
    }
}

private void btnAdd_Click(object sender, EventArgs e)
{
    if (fileName != null)
    {
        try
        {
            int counter = 0;
            string dest = Application.StartupPath + "\\photos\\" + fileName;
            string nameNoExtension = Path.GetFileNameWithoutExtension(fileName);
            string extension = Path.GetExtension(fileName);
            while (File.Exists(dest))
            {
                string newFileName = nameNoExtension + counter + extension;
                dest = Path.Combine(Application.StartupPath + "\\photos\\", newFileName);
                counter++;
            }
            File.Copy(fileNameToCopy, dest);
        }
        catch (Exception ex)
        {
            MessageBox.Show("Ошибка при копировании фото!",
                "Ошибка",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error);
            return;
        }
    }
}

